16	class PhpRedisConnector implements Connector
17	{
18	    /**
19	     * Create a new connection.
20	     *
21	     * @param  array  $config
22	     * @param  array  $options
23	     * @return \Illuminate\Redis\Connections\PhpRedisConnection
24	     */
25	    public function connect(array $config, array $options)
26	    {
27	        $formattedOptions = Arr::pull($config, 'options', []);
28	
29	        if (isset($config['prefix'])) {
30	            $formattedOptions['prefix'] = $config['prefix'];
31	        }
32	
33	        $connector = function () use ($config, $options, $formattedOptions) {
34	            return $this->createClient(array_merge(
35	                $config, $options, $formattedOptions
36	            ));
37	        };
38	
39	        return new PhpRedisConnection($connector(), $connector, $config);
40	    }
