42	    /**
43	     * Create a new clustered PhpRedis connection.
44	     *
45	     * @param  array  $config
46	     * @param  array  $clusterOptions
47	     * @param  array  $options
48	     * @return \Illuminate\Redis\Connections\PhpRedisClusterConnection
49	     */
50	    public function connectToCluster(array $config, array $clusterOptions, array $options)
51	    {
52	        $options = array_merge($options, $clusterOptions, Arr::pull($config, 'options', []));
53	
54	        return new PhpRedisClusterConnection($this->createRedisClusterInstance(
55	            array_map($this->buildClusterConnectionString(...), $config), $options
56	        ));
57	    }
58	
59	    /**
60	     * Build a single cluster seed string from an array.
61	     *
62	     * @param  array  $server
63	     * @return string
64	     */
65	    protected function buildClusterConnectionString(array $server)
66	    {
67	        return $this->formatHost($server).':'.$server['port'];
68	    }
69	
70	    /**
71	     * Create the Redis client instance.
72	     *
73	     * @param  array  $config
74	     * @return \Redis
75	     *
76	     * @throws \LogicException
77	     */
78	    protected function createClient(array $config)
79	    {
80	        return tap(new Redis, function ($client) use ($config) {
81	            if ($client instanceof RedisFacade) {
82	                throw new LogicException(
83	                    extension_loaded('redis')
84	                        ? 'Please remove or rename the Redis facade alias in your "app" configuration file in order to avoid collision with the PHP Redis extension.'
85	                        : 'Please make sure the PHP Redis extension is installed and enabled.'
86	                );
87	            }
88	
89	            $this->establishConnection($client, $config);
90	
91	            if (array_key_exists('max_retries', $config)) {
92	                $client->setOption(Redis::OPT_MAX_RETRIES, $config['max_retries']);
93	            }
94	
95	            if (array_key_exists('backoff_algorithm', $config)) {
96	                $client->setOption(Redis::OPT_BACKOFF_ALGORITHM, $this->parseBackoffAlgorithm($config['backoff_algorithm']));
97	            }
98	
99	            if (array_key_exists('backoff_base', $config)) {
100	                $client->setOption(Redis::OPT_BACKOFF_BASE, $config['backoff_base']);
101	            }
102	
103	            if (array_key_exists('backoff_cap', $config)) {
104	                $client->setOption(Redis::OPT_BACKOFF_CAP, $config['backoff_cap']);
105	            }
106	
107	            if (! empty($config['password'])) {
108	                if (isset($config['username']) && $config['username'] !== '' && is_string($config['password'])) {
109	                    $client->auth([$config['username'], $config['password']]);
110	                } else {
111	                    $client->auth($config['password']);
112	                }
113	            }
114	
115	            if (isset($config['database'])) {
116	                $client->select((int) $config['database']);
117	            }
118	
119	            if (! empty($config['prefix'])) {
120	                $client->setOption(Redis::OPT_PREFIX, $config['prefix']);
121	            }
122	
123	            if (! empty($config['read_timeout'])) {
124	                $client->setOption(Redis::OPT_READ_TIMEOUT, $config['read_timeout']);
125	            }
126	
127	            if (! empty($config['scan'])) {
128	                $client->setOption(Redis::OPT_SCAN, $config['scan']);
129	            }
130	
131	            if (! empty($config['name'])) {
132	                $client->client('SETNAME', $config['name']);
133	            }
134	
135	            if (array_key_exists('serializer', $config)) {
136	                $client->setOption(Redis::OPT_SERIALIZER, $config['serializer']);
137	            }
138	
139	            if (array_key_exists('compression', $config)) {
140	                $client->setOption(Redis::OPT_COMPRESSION, $config['compression']);
141	            }
142	
143	            if (array_key_exists('compression_level', $config)) {
144	                $client->setOption(Redis::OPT_COMPRESSION_LEVEL, $config['compression_level']);
145	            }
146	
147	            if (defined('Redis::OPT_PACK_IGNORE_NUMBERS') &&
148	                array_key_exists('pack_ignore_numbers', $config)) {
149	                $client->setOption(Redis::OPT_PACK_IGNORE_NUMBERS, $config['pack_ignore_numbers']);
150	            }
151	        });
152	    }
153	
154	    /**
155	     * Establish a connection with the Redis host.
156	     *
157	     * @param  \Redis  $client
158	     * @param  array  $config
159	     * @return void
160	     */
161	    protected function establishConnection($client, array $config)
162	    {
163	        $persistent = $config['persistent'] ?? false;
164	
165	        $parameters = [
166	            $this->formatHost($config),
167	            $config['port'],
168	            Arr::get($config, 'timeout', 0.0),
169	            $persistent ? Arr::get($config, 'persistent_id', null) : null,
170	            Arr::get($config, 'retry_interval', 0),
171	        ];
172	
173	        if (version_compare(phpversion('redis'), '3.1.3', '>=')) {
174	            $parameters[] = Arr::get($config, 'read_timeout', 0.0);
175	        }
176	
177	        if (version_compare(phpversion('redis'), '5.3.0', '>=') && ! is_null($context = Arr::get($config, 'context'))) {
178	            $parameters[] = $context;
179	        }
180	
181	        $client->{$persistent ? 'pconnect' : 'connect'}(...$parameters);
182	    }
183	
184	    /**
185	     * Create a new redis cluster instance.
186	     *
187	     * @param  array  $servers
188	     * @param  array  $options
189	     * @return \RedisCluster
190	     */
191	    protected function createRedisClusterInstance(array $servers, array $options)
192	    {
193	        $parameters = [
194	            null,
195	            array_values($servers),
196	            $options['timeout'] ?? 0,
197	            $options['read_timeout'] ?? 0,
198	            isset($options['persistent']) && $options['persistent'],
199	        ];
200	
201	        if (version_compare(phpversion('redis'), '4.3.0', '>=')) {
202	            $parameters[] = $options['password'] ?? null;
203	        }
204	
205	        if (version_compare(phpversion('redis'), '5.3.2', '>=') && ! is_null($context = Arr::get($options, 'context'))) {
206	            $parameters[] = $context;
207	        }
208	
209	        return tap(new RedisCluster(...$parameters), function ($client) use ($options) {
210	            if (! empty($options['prefix'])) {
211	                $client->setOption(Redis::OPT_PREFIX, $options['prefix']);
212	            }
213	
214	            if (! empty($options['scan'])) {
215	                $client->setOption(Redis::OPT_SCAN, $options['scan']);
216	            }
217	
218	            if (! empty($options['failover'])) {
219	                $client->setOption(RedisCluster::OPT_SLAVE_FAILOVER, $options['failover']);
220	            }
221	
222	            if (array_key_exists('serializer', $options)) {
223	                $client->setOption(Redis::OPT_SERIALIZER, $options['serializer']);
224	            }
225	
226	            if (array_key_exists('compression', $options)) {
227	                $client->setOption(Redis::OPT_COMPRESSION, $options['compression']);
228	            }
229	
230	            if (array_key_exists('compression_level', $options)) {
231	                $client->setOption(Redis::OPT_COMPRESSION_LEVEL, $options['compression_level']);
232	            }
233	        });
234	    }
235	
236	    /**
237	     * Format the host using the scheme if available.
238	     *
239	     * @param  array  $options
240	     * @return string
241	     */
242	    protected function formatHost(array $options)
243	    {
244	        if (isset($options['scheme'])) {
245	            return Str::start($options['host'], "{$options['scheme']}://");
246	        }
247	
248	        return $options['host'];
249	    }
250	
251	    /**
252	     * Parse a "friendly" backoff algorithm name into an integer.
253	     *
254	     * @param  mixed  $algorithm
255	     * @return int
256	     *
257	     * @throws \InvalidArgumentException
258	     */
259	    protected function parseBackoffAlgorithm(mixed $algorithm)
260	    {
261	        if (is_int($algorithm)) {
262	            return $algorithm;
263	        }
264	
265	        return match ($algorithm) {
266	            'default' => Redis::BACKOFF_ALGORITHM_DEFAULT,
267	            'decorrelated_jitter' => Redis::BACKOFF_ALGORITHM_DECORRELATED_JITTER,
268	            'equal_jitter' => Redis::BACKOFF_ALGORITHM_EQUAL_JITTER,
269	            'exponential' => Redis::BACKOFF_ALGORITHM_EXPONENTIAL,
270	            'uniform' => Redis::BACKOFF_ALGORITHM_UNIFORM,
271	            'constant' => Redis::BACKOFF_ALGORITHM_CONSTANT,
272	            default => throw new InvalidArgumentException("Algorithm [{$algorithm}] is not a valid PhpRedis backoff algorithm.")
273	        };
274	    }
275	}
